     AS x(variety_id uuid, ref_type text, title text, url text, publication_year int, authority text)
JOIN master_products p ON p.id = x.variety_id AND p.product_type = 'seed'
WHERE NOT EXISTS (SELECT 1 FROM variety_source_references s WHERE s.variety_id = x.variety_id AND s.url = x.url);

