e1b3", "crop_code": "linseed", "cultivation_method": "direct_seeded", "seed_rate_kg_per_ha_min": 12.0, "seed_rate_kg_per_ha_max": 15.0, "seed_rate_kg_per_acre_min": 4.856, "seed_rate_kg_per_acre_max": 6.07, "seed_rate_basis": "As printed for this variety: \"Seed Rate | 12-15 kg/ha\"", "spacing_row_cm": 30, "spacing_plant_cm": null, "duration_days_min": 115, "duration_days_max": 120, "duration_reference": "sowing", "source": "Dr. Panjabrao Deshmukh Krishi Vidyapeeth, Akola — https://www.pdkv.ac.in/?page_id=4536", "suitability_note": "Seed rate / spacing as printed in the variety source; not a stand-based calculation."}, {"variety_id": "a96c6a82-298a-44a9-bf02-37f8223c30c6", "crop_code": "linseed", "cultivation_method": "direct_seeded", "seed_rate_kg_per_ha_min": 25.0, "seed_rate_kg_per_ha_max": 25.0, "seed_rate_kg_per_acre_min": 10.117, "seed_rate_kg_per_acre_max": 10.117, "seed_rate_basis": "As printed for this variety: \"Seed Rate | 25 kg/ha\"", "spacing_row_cm": 30, "spacing_plant_cm": null, "duration_days_min": 97, "duration_days_max": 111, "duration_reference": "sowing", "source": "Dr. Panjabrao Deshmukh Krishi Vidyapeeth, Akola — https://www.pdkv.ac.in/?page_id=4536", "suitability_note": "Seed rate / spacing as printed in the variety source; not a stand-based calculation."}]$va$::jsonb)
     AS x(variety_id uuid, crop_code text, cultivation_method text, suitability_note text,
          seed_rate_kg_per_acre_min numeric, seed_rate_kg_per_acre_max numeric, seed_rate_kg_per_ha_min numeric,
          seed_rate_kg_per_ha_max numeric, seed_rate_basis text, seed_rate_basis_code text, spacing_row_cm numeric,
          spacing_plant_cm numeric, duration_days_min int, duration_days_max int, duration_reference text, source text)
JOIN master_products p ON p.id = x.variety_id AND p.product_type = 'seed'
ON CONFLICT (variety_id, cultivation_method) DO NOTHING;

-- =====================================================================================
-- CHECK (read-only) — run after this file and the two translation files.
-- Before running on 3 Oct 2026 the counts were: detail_filled 0, with_maturity 0, with_yield 0,
-- with_description 0, translation_rows 0, resistance_rows 0, source_rows 282, review_rows 55, agronomy_rows 0.
-- =====================================================================================
WITH v AS (SELECT id, metadata->>'load_batch' AS batch, metadata, maturity_days_max, yield_potential_qtl_per_acre, description
           FROM master_products WHERE product_type = 'seed'
             AND metadata->>'load_batch' IN ('veg_variety_region_2026_10_03', 'pulse_oilseed_variety_region_2026_10_03'))
SELECT v.batch, count(*) AS varieties,
       count(*) FILTER (WHERE v.metadata->>'detail_batch' = 'variety_detail_2026_10_03') AS detail_filled,
       count(*) FILTER (WHERE v.maturity_days_max IS NOT NULL) AS with_maturity,
       count(*) FILTER (WHERE v.yield_potential_qtl_per_acre IS NOT NULL) AS with_yield,
       count(*) FILTER (WHERE NULLIF(v.description, '') IS NOT NULL) AS with_description,
       sum((SELECT count(*) FROM variety_translations t WHERE t.variety_id = v.id)) AS translation_rows,
       sum((SELECT count(*) FROM variety_resistance r WHERE r.variety_id = v.id)) AS resistance_rows,
       sum((SELECT count(*) FROM variety_source_references s WHERE s.variety_id = v.id)) AS source_rows,
       sum((SELECT count(*) FROM variety_review_queue q WHERE q.variety_id = v.id)) AS review_rows,
       sum((SELECT count(*) FROM variety_cultivation_agronomy a WHERE a.variety_id = v.id)) AS agronomy_rows
FROM v GROUP BY v.batch ORDER BY v.batch;
